import java.util.*;
class PoolModel {static class Request{int at,replica,duration,start=-1,end=-1;boolean leak;String state="future";Request(int a,int r,int d,boolean l){at=a;replica=r;duration=d;leak=l;}}static class Connection{int replica,request=-1;boolean leaked;Connection(int r){replica=r;}}List<Connection>connections=new ArrayList<>();int poolSize,databaseLimit;PoolModel(int p,int d){poolSize=p;databaseLimit=d;}
boolean acquire(List<Request>requests,int id,int tick){Request r=requests.get(id);Connection slot=null;int owned=0;for(Connection c:connections)if(c.replica==r.replica){owned++;if(c.request==-1&&!c.leaked)slot=c;}if(slot==null&&connections.size()<databaseLimit&&owned<poolSize){slot=new Connection(r.replica);connections.add(slot);}if(slot==null)return false;slot.request=id;r.state="running";r.start=tick;r.end=tick+r.duration;return true;}
void run(List<Request>requests,int ticks,int timeout,int queueLimit){for(int tick=0;tick<ticks;tick++){for(Connection c:connections)if(c.request>=0&&!c.leaked){Request r=requests.get(c.request);if(r.end<=tick){r.state="done";if(r.leak)c.leaked=true;else c.request=-1;}}
for(Request r:requests)if(r.state.equals("waiting")&&tick-r.at>=timeout)r.state="timeout";List<Integer>waitingIds=new ArrayList<>();for(int i=0;i<requests.size();i++)if(requests.get(i).state.equals("waiting"))waitingIds.add(i);waitingIds.sort(Comparator.comparingInt((Integer i)->requests.get(i).at).thenComparingInt(i->i));for(int id:waitingIds)acquire(requests,id,tick);
for(int id=0;id<requests.size();id++){Request r=requests.get(id);if(!r.state.equals("future")||r.at!=tick)continue;int waiting=0;for(Request other:requests)if(other.state.equals("waiting")&&other.replica==r.replica)waiting++;if(waiting>0||!acquire(requests,id,tick))r.state=waiting>=queueLimit?"rejected":"waiting";}}}}
// FIFO acquisition waits differ from query execution duration and query timeouts.
// Replica-local idle ownership cannot be borrowed by another pool.
